                <Pencil className="size-4" />
                {t("referral_edit")}
              </DropdownMenuItem>
              <DropdownMenuSeparator />
              <DropdownMenuLabel>
                {t("referral_change_status")}
              </DropdownMenuLabel>
              {REFERRAL_STATUSES.filter(
                (status) => status !== referral.status,
              ).map((status) => (
                <DropdownMenuItem
                  key={status}
                  variant={
                    ["cancelled", "rejected"].includes(status)
                      ? "destructive"
                      : "default"
                  }
                  onSelect={() => confirmStatus(status)}
