              ))}
            </>
          )}
          {onCopyLink && (
            <>
              {canWrite && <DropdownMenuSeparator />}
              <DropdownMenuItem onSelect={() => void onCopyLink()}>
                <Copy className="size-4" />
                {t("copy_link")}
