                aria-label={t("referral_respond")}
                className="rounded-xl border border-border bg-background p-4 sm:p-6"
              >
                <h1 className="mb-5 text-xl font-semibold">
                  {t("referral_respond")}
                </h1>
                {contextWarning}
                {form}
              </section>
            </div>
          </div>
          <div className="bg-background">{footer}</div>
        </FillSessionTabs>
      ) : (
