                      ? "referral_form_type_response"
                      : "referral_request_information",
                  )}
                </TabsTrigger>
                <TabsTrigger value="request">
                  {t("referral_response_request_tab")}
                </TabsTrigger>
              </TabsList>
            </div>
            <div className="min-h-0 flex-1 overflow-y-auto p-4 sm:p-5">
              <TabsContent
                value="response"
                keepMounted
                hidden={tab !== "response"}
              >
                {form}
              </TabsContent>
              <TabsContent value="request">{context}</TabsContent>
            </div>
          </Tabs>
          {footer}
        </DialogContent>
      )}
      <AlertDialog
        open={!!discardAction}
        onOpenChange={(value) => {
          if (!value) setDiscardAction(undefined);
        }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              {t(
                responseOnly
                  ? "referral_response_discard_title"
                  : "discard_changes",
              )}
            </AlertDialogTitle>
            <AlertDialogDescription>
              {t("referral_response_discard_description")}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>
              {t("referral_response_keep_editing")}
            </AlertDialogCancel>
            <Button
              variant="destructive"
              onClick={() => {
                const action = discardAction;
                setDiscardAction(undefined);
                if (action?.type === "change") changeForm(action.formId);
                else closeEditor();
              }}
            >
              {t("discard")}
            </Button>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

