            </AlertDialogDescription>
          </AlertDialogHeader>
          {update.error && (
            <FieldError role="alert">
              {referralResourceError(update.error, t("referral_update_failed"))}
            </FieldError>
          )}
          <AlertDialogFooter>
            <AlertDialogCancel disabled={update.isPending}>
              {t("cancel")}
