          <Field>
            <FieldLabel>{t("referral_record_type")}</FieldLabel>
            <Select
              value={resourceType}
              disabled={add.isPending}
              onValueChange={(value: ReferralResourceType) => {
                setResourceType(value);
                resetSelection();
              }}
            >
              <SelectTrigger aria-label={t("referral_record_type")}>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {REFERRAL_ATTACHABLE_RESOURCE_TYPES.map((type) => (
                  <SelectItem key={type} value={type}>
                    {t(`referral_resource_${type}`)}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </Field>
          <ReferralResourceCategoryField
            value={category}
            onChange={setCategory}
            disabled={add.isPending}
            categories={categories}
          />
        </div>
        {receivingEncounter && scopedClinicalType && (
          <Field>
            <FieldLabel>{t("referral_record_scope")}</FieldLabel>
            <Select
              value={recordScope}
              disabled={add.isPending}
              onValueChange={(value) => {
                setRecordScope(value);
                resetSelection();
              }}
            >
              <SelectTrigger aria-label={t("referral_record_scope")}>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="encounter">
                  {t("referral_receiving_encounter")}
                </SelectItem>
                <SelectItem value="patient">
                  {t("referral_all_patient_records")}
                </SelectItem>
              </SelectContent>
            </Select>
          </Field>
        )}
        {resourceType === "file_upload" && (
          <Field>
            <FieldLabel>{t("referral_file_source")}</FieldLabel>
            <Select
              value={fileScope}
              disabled={add.isPending}
              onValueChange={(value: FileType) => {
                setFileScope(value);
                resetSelection();
                if (value === FileType.ENCOUNTER && receivingEncounter) {
                  setParent({
                    id: receivingEncounter.id,
                    title: receivingEncounter.facility.name,
                  });
                }
              }}
            >
              <SelectTrigger aria-label={t("referral_file_source")}>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {[
                  FileType.PATIENT,
                  FileType.ENCOUNTER,
                  FileType.CONSENT,
                  FileType.REFERRAL,
                  FileType.DIAGNOSTIC_REPORT,
                  FileType.SERVICE_REQUEST,
                ].map((scope) => (
                  <SelectItem key={scope} value={scope}>
                    {t(`referral_file_source_${scope}`)}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </Field>
        )}
        {needsFacility && (
          <Field>
            <FieldLabel>{t("facility")}</FieldLabel>
            <Select
              value={facilityId}
              disabled={add.isPending}
              onValueChange={(value) => {
                setFacilityId(value);
                resetSelection();
              }}
            >
              <SelectTrigger aria-label={t("facility")}>
                <SelectValue placeholder={t("select_facility")} />
              </SelectTrigger>
              <SelectContent>
                {facilities.map((facility) => (
                  <SelectItem key={facility.id} value={facility.id}>
                    {facility.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </Field>
        )}
        {parent && (
          <div className="flex items-center gap-2">
            <Button
              variant="ghost"
              size="sm"
              onClick={resetSelection}
              disabled={add.isPending}
            >
              <ArrowLeft className="size-4" />
              {t("back")}
            </Button>
            <p className="min-w-0 truncate text-sm text-muted-foreground">
              {parent.title}
            </p>
          </div>
        )}
        {choosingParent && (
          <p className="text-sm text-muted-foreground">
            {t("referral_choose_parent_record")}
          </p>
        )}
        <div className="space-y-2" aria-busy={candidates.isFetching}>
          {candidates.isLoading ? (
            <p role="status" className="flex items-center gap-2 py-6 text-sm">
              <Spinner className="size-4 animate-spin" />
              {t("loading")}
            </p>
          ) : candidates.isError ? (
            <div role="alert" className="space-y-2 py-4">
              <p className="text-sm text-muted-foreground">
                {t("referral_records_load_error")}
              </p>
              <Button
                variant="outline"
                onClick={() => void candidates.refetch()}
              >
                {t("retry")}
              </Button>
            </div>
          ) : choices.length === 0 ? (
            <p className="py-6 text-sm text-muted-foreground">
              {needsFacility && !facilityId
                ? t("select_facility")
                : t("referral_no_available_records")}
            </p>
          ) : (
            choices.map((candidate) => {
              const attached = !choosingParent && attachedIds.has(candidate.id);
              return (
                <Item
                  key={candidate.id}
                  variant="outline"
                  size="sm"
                  className={
                    selected?.id === candidate.id
                      ? "border-primary bg-accent"
                      : ""
                  }
                >
                  <ItemContent>
                    <ItemTitle className="break-words">
                      {candidate.title || t(`referral_resource_${listingType}`)}
                    </ItemTitle>
                    {candidate.detail && (
                      <ItemDescription className="break-words">
                        {candidate.detail}
                      </ItemDescription>
                    )}
                  </ItemContent>
                  <Button
                    size="sm"
                    variant={
                      selected?.id === candidate.id ? "secondary" : "outline"
                    }
                    disabled={attached || add.isPending}
                    aria-pressed={
                      !choosingParent && selected?.id === candidate.id
                    }
                    aria-label={t("referral_select_record", {
                      name:
                        candidate.title ||
                        t(`referral_resource_${listingType}`),
                    })}
                    onClick={() => {
                      if (choosingParent) {
                        setParent(candidate);
                        setOffset(0);
                      } else setSelected(candidate);
                    }}
                  >
                    {selected?.id === candidate.id && (
                      <Check className="size-4" />
                    )}
                    {attached
                      ? t("referral_record_attached")
                      : choosingParent
                        ? t("open")
                        : t("select")}
                  </Button>
                </Item>
              );
            })
          )}
        </div>
        {(candidates.data?.count ?? 0) > REFERRAL_CANDIDATE_PAGE_SIZE &&
          listingType !== "specimen" && (
            <div className="flex justify-between gap-2">
              <Button
                variant="outline"
                size="sm"
                disabled={
                  offset === 0 || candidates.isFetching || add.isPending
                }
                onClick={() => {
                  setOffset(Math.max(0, offset - REFERRAL_CANDIDATE_PAGE_SIZE));
                  setSelected(undefined);
                }}
              >
                {t("previous")}
              </Button>
              <Button
                variant="outline"
                size="sm"
                disabled={
                  offset + REFERRAL_CANDIDATE_PAGE_SIZE >=
                    (candidates.data?.count ?? 0) ||
                  candidates.isFetching ||
                  add.isPending
                }
                onClick={() => {
                  setOffset(offset + REFERRAL_CANDIDATE_PAGE_SIZE);
                  setSelected(undefined);
                }}
              >
                {t("next")}
              </Button>
            </div>
          )}
        {add.isError && (
          <FieldError role="alert">
            {referralResourceError(add.error, t("referral_record_share_error"))}
          </FieldError>
        )}
        <DialogFooter>
          <Button variant="outline" disabled={add.isPending} onClick={onClose}>
            {t("cancel")}
          </Button>
          <Button
            disabled={!selected || add.isPending}
            onClick={() => {
              if (!selected) return;
              const resource: ReferralResourceCreate = {
                resource_type: resourceType,
                resource_id: selected.id,
                attachment_type: category,
                metadata: selected.metadata,
              };
              add.mutate(resource);
            }}
          >
            {add.isPending && <Spinner className="size-4 animate-spin" />}
            {t("referral_add_record")}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

