import { Spinner } from "@/components/ui/spinner";
import {
  useInfiniteQuery,
  useMutation,
  useQueryClient,
} from "@tanstack/react-query";
import {
  Activity,
  CalendarDays,
  ClipboardList,
  ClipboardPlus,
  Ellipsis,
  Eye,
  FileAudio,
  FileImage,
  FileSpreadsheet,
  FileText,
  FileVideo,
  Files,
  FlaskConical,
  Link2,
  type LucideIcon,
  Plus,
  ShieldAlert,
  Stethoscope,
  Syringe,
  TestTubeDiagonal,
  Trash2,
  Upload,
} from "lucide-react";
import { type ReactNode, useEffect, useId, useRef, useState } from "react";
