import { Spinner } from "@/components/ui/spinner";
import {
  useInfiniteQuery,
  useMutation,
  useQueryClient,
} from "@tanstack/react-query";
import {
  Activity,
  CalendarDays,
  ClipboardList,
  ClipboardPlus,
  Ellipsis,
  Eye,
  FileAudio,
  FileImage,
  FileSpreadsheet,
  FileText,
  FileVideo,
  Files,
  FlaskConical,
  Link2,
  type LucideIcon,
  Network,
  Plus,
  ShieldAlert,
  Stethoscope,
  Syringe,
  TestTubeDiagonal,
  Trash2,
  Upload,
} from "lucide-react";
import { type ReactNode, useEffect, useId, useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import FilePreviewDialog from "@/components/Common/FilePreviewDialog";
import {
  AlertDialog,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
