  ClipboardPlus,
  Ellipsis,
  Eye,
  FileAudio,
  FileImage,
  FileSpreadsheet,
  FileText,
  FileVideo,
  Files,
  FlaskConical,
  Link2,
  type LucideIcon,
  Network,
  Plus,
  ShieldAlert,
  Stethoscope,
  Syringe,
  TestTubeDiagonal,
  Trash2,
  Upload,
} from "lucide-react";
import { type ReactNode, useEffect, useId, useRef, useState } from "react";
import { useTranslation } from "react-i18next";
